function deepFind(node: any, pred: (v: any) => boolean): any | undefined {
  if (node === null || typeof node !== 'object') return undefined;
  if (pred(node)) return node;
  if (Array.isArray(node)) {
    for (const child of node) { const found = deepFind(child, pred); if (found) return found; }
  } else {
    for (const key of Object.keys(node)) { const found = deepFind(node[key], pred); if (found) return found; }
  }
  return undefined;
}
```

