import { TestBed } from '@angular/core/testing';
import { TmdbMovie, WatchItem } from '../app/movie';
import { WatchlistStore } from '../app/watchlist-store';

function tmdbMovie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-01-01',
    poster_path: null,
    overview: 'Overview of ' + title,
  };
}

function tryFlushTestBedEffects(): void {
  try {
    (TestBed as unknown as { flushEffects?: () => void }).flushEffects?.();
  } catch {
    // best-effort: the timers awaited below settle effects regardless
  }
}

async function settleEffects(): Promise<void> {
  tryFlushTestBedEffects();
  await Promise.resolve();
  tryFlushTestBedEffects();
  await new Promise<void>((resolve) => setTimeout(resolve, 0));
  tryFlushTestBedEffects();
  if (typeof requestAnimationFrame === 'function') {
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
    tryFlushTestBedEffects();
  }
}

function deepFind(node: unknown, pred: (value: unknown) => boolean): unknown {
  if (typeof node !== 'object' || node === null) {
    return undefined;
  }
  if (pred(node)) {
    return node;
  }
  if (Array.isArray(node)) {
    for (const child of node) {
      const found = deepFind(child, pred);
      if (found !== undefined) {
        return found;
      }
    }
    return undefined;
  }
  for (const key of Object.keys(node)) {
    const found = deepFind((node as Record<string, unknown>)[key], pred);
    if (found !== undefined) {
      return found;
    }
  }
  return undefined;
}

function findPersistedItem(id: number): Record<string, unknown> | undefined {
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    const raw = key === null ? null : localStorage.getItem(key);
    if (raw === null) {
      continue;
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      continue;
    }
    const found = deepFind(parsed, (value) => {
      if (typeof value !== 'object' || value === null) {
        return false;
      }
      return (value as Record<string, unknown>)['id'] === id;
    });
    if (found !== undefined) {
      return found as Record<string, unknown>;
    }
  }
  return undefined;
}

describe('WatchlistStore', () => {
  beforeEach(() => {
    TestBed.resetTestingModule();
    localStorage.clear();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
  });

  afterEach(() => {
    localStorage.clear();
  });

  it('adds movies as unseen and toggleWatched flips the seen flag', async () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(1, 'Test Movie'));
    await settleEffects();

    expect(store.count()).toBe(1);
    expect(store.items()).toHaveLength(1);
    const item = store.items()[0] as WatchItem & Record<string, unknown>;
    expect(item.title).toBe('Test Movie');
    expect(item.seen).toBe(false);
    expect('watched' in item).toBe(false);

    store.toggleWatched(1);
    await settleEffects();
    expect((store.items()[0] as WatchItem).seen).toBe(true);

    store.toggleWatched(1);
    await settleEffects();
    expect((store.items()[0] as WatchItem).seen).toBe(false);
  });

  it('watchedCount counts the items whose seen flag is true', async () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(1, 'First Movie'));
    store.add(tmdbMovie(2, 'Second Movie'));
    await settleEffects();
    expect(store.watchedCount()).toBe(0);

    store.toggleWatched(1);
    await settleEffects();
    expect(store.watchedCount()).toBe(1);

    store.toggleWatched(2);
    await settleEffects();
    expect(store.watchedCount()).toBe(2);

    store.toggleWatched(1);
    await settleEffects();
    expect(store.watchedCount()).toBe(1);
    expect(store.count()).toBe(2);
  });

  it('persists the flag under the name seen', async () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(42, 'Persisted Movie'));
    store.add(tmdbMovie(43, 'Second Movie'));
    store.toggleWatched(42);
    await settleEffects();

    const persisted = findPersistedItem(42);
    expect(persisted).toBeDefined();
    if (persisted === undefined) {
      return;
    }
    expect(persisted['seen']).toBe(true);
    expect('watched' in persisted).toBe(false);

    const second = findPersistedItem(43);
    expect(second).toBeDefined();
    if (second === undefined) {
      return;
    }
    expect(second['seen']).toBe(false);
    expect('watched' in second).toBe(false);
  });
});
